window.ScripturaLexicons.THAYER.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0301\" data-source=\"THAYER\" data-search=\"Ἀμπλιᾶτος nome próprio masculino, -ου Amplíato; cristão em Roma Rm 16.8 Thayer 32–33\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμπλιᾶτος</td><td>nome próprio masculino, -ου</td><td>Amplíato; cristão em Roma</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0302\" data-source=\"THAYER\" data-search=\"Ἀμπλίατος nome próprio masculino; entrada remissiva variante do nome Amplíato Rm 16.8 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμπλίατος</td><td>nome próprio masculino; entrada remissiva</td><td>variante do nome Amplíato</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0303\" data-source=\"THAYER\" data-search=\"ἀμύνω verbo; médio ἀμύνομαι afastar; defender; socorrer; vingar-se At 7.24 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμύνω</td><td>verbo; médio ἀμύνομαι</td><td>afastar; defender; socorrer; vingar-se</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0304\" data-source=\"THAYER\" data-search=\"ἀμφιάζω verbo em -άζω vestir; revestir de roupa Lc 12.28 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιάζω</td><td>verbo em -άζω</td><td>vestir; revestir de roupa</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0305\" data-source=\"THAYER\" data-search=\"ἀμφιβάλλω verbo composto lançar ao redor; lançar rede Mc 1.16 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιβάλλω</td><td>verbo composto</td><td>lançar ao redor; lançar rede</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0306\" data-source=\"THAYER\" data-search=\"ἀμφίβληστρον substantivo neutro, -ου rede de lançamento; tarrafa Mt 4.18; Mc 1.16 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφίβληστρον</td><td>substantivo neutro, -ου</td><td>rede de lançamento; tarrafa</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0307\" data-source=\"THAYER\" data-search=\"ἀμφιέζω verbo; entrada remissiva vestir; variante de ἀμφιέννυμι Lc 12.28 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιέζω</td><td>verbo; entrada remissiva</td><td>vestir; variante de ἀμφιέννυμι</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0308\" data-source=\"THAYER\" data-search=\"ἀμφιέννυμι verbo; perfeito passivo ἠμφίεσμαι vestir; cobrir com vestes Mt 6.30; 11.8; Lc 7.25; 12.28 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιέννυμι</td><td>verbo; perfeito passivo ἠμφίεσμαι</td><td>vestir; cobrir com vestes</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0309\" data-source=\"THAYER\" data-search=\"Ἀμφίπολις nome próprio feminino, -εως Anfípolis; cidade da Macedônia At 17.1 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμφίπολις</td><td>nome próprio feminino, -εως</td><td>Anfípolis; cidade da Macedônia</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0310\" data-source=\"THAYER\" data-search=\"ἄμφοδον substantivo neutro, -ου rua; via que circunda algo; quarteirão Mc 11.4 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμφοδον</td><td>substantivo neutro, -ου</td><td>rua; via que circunda algo; quarteirão</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0311\" data-source=\"THAYER\" data-search=\"ἀμφότεροι adjetivo/pronome plural, -αι, -α ambos; os dois Mt 9.17; At 23.8; Ef 2.14 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφότεροι</td><td>adjetivo/pronome plural, -αι, -α</td><td>ambos; os dois</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0312\" data-source=\"THAYER\" data-search=\"ἀμώμητος adjetivo, -ον sem censura; irrepreensível Fp 2.15 (variante); 2Pe 3.14 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμώμητος</td><td>adjetivo, -ον</td><td>sem censura; irrepreensível</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0313\" data-source=\"THAYER\" data-search=\"ἄμωμον substantivo neutro, -ου amomo; planta aromática Ap 18.13 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμωμον</td><td>substantivo neutro, -ου</td><td>amomo; planta aromática</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0314\" data-source=\"THAYER\" data-search=\"ἄμωμος adjetivo, -ον sem defeito; imaculado; irrepreensível 1Pe 1.19; Hb 9.14; Ef 1.4; 5.27; Cl 1.22; Jd 24; Ap 14.5 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμωμος</td><td>adjetivo, -ον</td><td>sem defeito; imaculado; irrepreensível</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0315\" data-source=\"THAYER\" data-search=\"Ἀμών nome próprio masculino indeclinável Amom; rei de Judá Mt 1.10 (variante) Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμών</td><td>nome próprio masculino indeclinável</td><td>Amom; rei de Judá</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0316\" data-source=\"THAYER\" data-search=\"Ἀμώς nome próprio masculino indeclinável Amós; ancestral de Jesus Mt 1.10 (variante); Lc 3.25 Thayer 33\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμώς</td><td>nome próprio masculino indeclinável</td><td>Amós; ancestral de Jesus</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0317\" data-source=\"THAYER\" data-search=\"ἄν partícula modal partícula de possibilidade, condição e eventualidade Lc 7.39; 17.6; Mt 11.21; Jo 4.10; 14.2; Rm 9.29; 1Co 2.8; Mc 6.10; Mt 10.11; Ap 2.25 Thayer 33–34\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄν</td><td>partícula modal</td><td>partícula de possibilidade, condição e eventualidade</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0318\" data-source=\"THAYER\" data-search=\"ἀνά preposição com acusativo e elemento de compostos acima; para cima; ao longo de; por; cada; de novo em composição Mt 13.25; Mc 7.31; Ap 7.17; Jo 2.6; 1Co 14.27; Mt 20.17 Thayer 34–35\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνά</td><td>preposição com acusativo e elemento de compostos</td><td>acima; para cima; ao longo de; por; cada; de novo em composição</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n";
window.ScripturaLexicons.THAYER.cardsHtml+="<article id=\"entry-thayer-0301\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"32–33\" data-thayer-pdf-leaf=\"56\" data-thayer-column=\"direita (32); esquerda (33)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀμπλιᾶτος\" data-meanings=\"Amplíato; cristão em Roma\">Ἀμπλιᾶτος</h1><div class=\"entry-meta\">nome próprio masculino, -ου · Thayer, p. 32–33, direita (32); esquerda (33)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">Ἀμπλιᾶτος, -ου, ὁ, nome de um cristão em Roma mencionado em Romanos 16.8. Thayer discute as grafias Ἀμπλιᾶτος e Ἀμπλίας como formas ligadas ao latim *Ampliatus* e registra variantes de acentuação e leitura nas edições críticas. A entrada começa na página 32 e continua na 33.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Rm 16.8</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 32–33, folhas PDF 56–57, coluna direita (32); esquerda (33). O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">&quot;Apmdtas [T ’AumAlatos, Tr WH Limrg. ’Aumdcazos; \nhence accent &quot;Auras; cf. Lob. Pathol. Proleg. p. 505; \nChandler § 32], -ov, 6, Amplias (a contraction from the \nLat. Ampliatus, which form appears in some authorities, \nSee dpviov.*\n[continua p. 33]\n-Aurrlatos \ncf. W. 102 (97)), a certain Christian at Rome: Ro. xvi. 8. [See Bp. Lghtft. on Phil. p.174; ef. The Athenewm \nfor March 4, 1882, p. 289 sq.]*</p></section></article>\n<article id=\"entry-thayer-0302\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀμπλίατος\" data-meanings=\"variante do nome Amplíato\">Ἀμπλίατος</h1><div class=\"entry-meta\">nome próprio masculino; entrada remissiva · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">Ἀμπλίατος, forma atestada por Tischendorf, é apresentada como entrada de remissão à forma Ἀμπλιᾶτος segundo outras edições. Trata-se de um cabeçalho próprio no impresso, sem designar outro indivíduo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Rm 16.8</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">*&quot;ApmAlaros (Tdf.) or more correctly ’Ayrhdros (L \nmrg. Tr WH) i. q. ’AumAias, q. v.</p></section></article>\n<article id=\"entry-thayer-0303\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμύνω\" data-meanings=\"afastar; defender; socorrer; vingar-se\">ἀμύνω</h1><div class=\"entry-meta\">verbo; médio ἀμύνομαι · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμύνω: afastar ou repelir algo de alguém; auxiliar, socorrer. Na voz média ἀμύνομαι, afastar de si um agressor, defender-se e, em determinados contextos, vingar-se. Atos 7.24 refere-se à defesa do israelita oprimido por Moisés. Thayer assinala primeiro aoristo médio ἠμυνάμην e paralelos de Tucídides, Xenofonte, Josefo, 2Macabeus e Sabedoria.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">At 7.24</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dpive: 1 aor. mid. jyuvdunv; [allied w. Lat. munio, \nmoenia, ete., Waniéek p. 731; Curtius § 451]; in Grk. \nwrit. [fr. Hom. down] to ward off, keep off any thing \nfrom any one, ri ru, ace. of the thing and dat. of pers. ; \nhence, with a simple dat. of the pers., to aid, assist any \none (Thue. 1, 50; 3, 67, al.). Mid. dydvoua, with ace. \nof pers., to keep off, ward off, any one from one’s self; to \ndefend one’s self against any one (so also 2 Mace. x. 17; \nSap. xi. 3; Sept. Josh. x. 13); to take vengeance on any \none (Xen. an. 2, 3, 23; Joseph. antt. 9, 1, 2): Acts vii. \n24, where in thought supply rdv ddcKodvra [cf. B. 194 \n(168) note; W. 258 (242) ].*</p></section></article>\n<article id=\"entry-thayer-0304\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιάζω\" data-meanings=\"vestir; revestir de roupa\">ἀμφιάζω</h1><div class=\"entry-meta\">verbo em -άζω · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφιάζω, «vestir, cobrir com roupa», aparece em Lucas 12.28 como leitura de Lachmann e Westcott–Hort contra ἀμφιέννυσιν do texto recebido. Thayer apresenta referências ao grego posterior, à Septuaginta e às variantes gramaticais. Remete a ἀμφιέζω e ἀμφιέννυμι.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Lc 12.28 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">audidte; [fr. dudi, lit. to put around]; to put on, \nclothe: in Lk. xii. 28 L WH dyquager for Rec. dueévvvcr. \n(A later Grk. word; Sept. [2 K. xvii. 9 Alex.]; Job \nxxix. 14; [xxxi.19]; xl.5; Ps. lxxii. 6 Symm.; several \ntimes in Themist.; cf. Bttm. Ausf. Spr. ii. p. 112; [Veitch \ns.v.; B.49 (42 sq.) ; Steph. s. v. col. 201 ec. quotes from \nCram. Anecdot. Ox. vol. ii. p. 338, 31 76 peév audiélo éort \nkowas, TO be audidla Awpixdv, Gomep TO Umoméfw Kal \nimondta}.) Cf. audreto.*</p></section></article>\n<article id=\"entry-thayer-0305\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιβάλλω\" data-meanings=\"lançar ao redor; lançar rede\">ἀμφιβάλλω</h1><div class=\"entry-meta\">verbo composto · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφιβάλλω: lançar em volta, envolver algo, ou lançar uma rede para pescar. Marcos 1.16 em algumas edições críticas, com verbo empregado sem objeto expresso; o texto é comparado com Isaías 19.8 e Habacuque 1.17 e com o verbo περιβάλλω.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mc 1.16 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">apdi-Badrw ; to throw around, i. q. repiBadrdo, of a gar￾ment (Hom. Od. 14, 342); to cast to and fro now to one \nside now to the other: anet, Mk.i.16 GL T Tr WH [ace. \nto T Tr WH used absol.; cf. of dudiBoreis, Is. xix. 8]. \n(Hab. i. 17.)*</p></section></article>\n<article id=\"entry-thayer-0306\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφίβληστρον\" data-meanings=\"rede de lançamento; tarrafa\">ἀμφίβληστρον</h1><div class=\"entry-meta\">substantivo neutro, -ου · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφίβληστρον, -ου, τό: objeto lançado em volta de alguém para impedir movimentos; especialmente rede circular arremessada para pesca, tarrafa. Mateus 4.18; Marcos 1.16 na leitura do texto recebido. Thayer remete à comparação técnica de δίκτυον e de outros tipos de redes, com referência a Trench §64.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 4.18; Mc 1.16 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dpdiBAnotpov, -ov, 7d, (aupuBddd@), in Grk. writ. any￾thing thrown around one to impede his motion, as chains, \na garment; spec. a net for fishing, [casting-net]: Mk. i. \n16 RGL; Mt.iv.18. (Sept.; Hes. scut. 215; Hat. 1, \n141; Athen. 10, 72, p. 450.) [Syn. see dicrvoy, and cf. \nTrench § lxiv.; B. D.s. v. net. ]*</p></section></article>\n<article id=\"entry-thayer-0307\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιέζω\" data-meanings=\"vestir; variante de ἀμφιέννυμι\">ἀμφιέζω</h1><div class=\"entry-meta\">verbo; entrada remissiva · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφιέζω: forma relacionada a ἀμφιέννυμι com o sentido «vestir, revestir». Em Lucas 12.28, certas edições críticas apresentam esta forma. Thayer remete aos artigos ἀμφιάζω e ἀμφιέννυμι; trata-se de registro independente na sequência impressa.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Lc 12.28 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dudréto, i. g. dudrevvype; in Lk. xii. 28 duduéCer T Tr. \nCf. audidgo.</p></section></article>\n<article id=\"entry-thayer-0308\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιέννυμι\" data-meanings=\"vestir; cobrir com vestes\">ἀμφιέννυμι</h1><div class=\"entry-meta\">verbo; perfeito passivo ἠμφίεσμαι · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφιέννυμι: vestir alguém, revestir de vestuário; perfeito passivo ἠμφίεσμαι. Emprego em Mateus 6.30; 11.8; Lucas 7.25 e 12.28 segundo o texto recebido, onde há variantes de ἀμφιάζω e ἀμφιέζω. Em Lucas 7.25 aparece com dativo relativo ao vestuário.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 6.30; 11.8; Lc 7.25; 12.28</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">_dudvévyupe; pf. pass. nudiecpar; (€vvume); [fr. Hom. \ndown]; to put on, to clothe: Lk. xii. 28 (RG; cf. auduego) ; \nMt. vi. 30; év rue [B. 191 (166) ], Lk. vii. 25; Mt. xi. 8.*</p></section></article>\n<article id=\"entry-thayer-0309\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀμφίπολις\" data-meanings=\"Anfípolis; cidade da Macedônia\">Ἀμφίπολις</h1><div class=\"entry-meta\">nome próprio feminino, -εως · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">Ἀμφίπολις, -εως, ἡ: Anfípolis, capital de Macedônia Prima, cujo nome, segundo a explicação histórica de Thayer, relaciona-se ao curso do rio Estrimão ao redor da cidade. Antigo nome: Ἐννέα Ὁδοί, «Nove Caminhos». Atos 17.1. O artigo cita Tucídides e dicionários bíblicos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">At 17.1</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">*Apdlrodis, -ews, 7, Amphipolis, the metropolis of \nMacedonia Prima [cf. B. D. s. v. Macedonia]; so called, \nbecause the Strymon flowed around it [ Thue. 4, 102]; \nformerly called ’Evvéa 680i (Thue. 1,100): Acts xvii. 1 \n[see B. D.].*</p></section></article>\n<article id=\"entry-thayer-0310\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμφοδον\" data-meanings=\"rua; via que circunda algo; quarteirão\">ἄμφοδον</h1><div class=\"entry-meta\">substantivo neutro, -ου · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἄμφοδον, -ου, τό, de ἀμφί e ὁδός: caminho ao redor de um objeto; via ou rua, possivelmente quarteirão formado por vias. Marcos 11.4. Thayer transcreve glosas de Hesíquio e léxicos antigos e remete a exemplos da Septuaginta e de escritores gregos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mc 11.4</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">&amp;pdodov, -ov, 75, (dui, 656s), prop. 4 road round any￾thing, a street, [Hesych. dugpoda- af prpat. dyuiat. diodo \n(al. d:€€080e Stopvypai, al. ) mAareia); Lex. in Bekk. An￾ecdota i. p. 205, 14 &quot;Audodov: 7 Somep ex Terpayovou \nSuryeypappérn 686s. For exx. see Soph. Lex.; Wetst. on \nMk. 1. c.; cod. D in Acts xix. 28 (where see Tdf.’s \nnote)]: Mk. xi.4. (Jer. xvii. 27; xxx. 16 (xlix. 27), and \nin Grk. writ.) *</p></section></article>\n<article id=\"entry-thayer-0311\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφότεροι\" data-meanings=\"ambos; os dois\">ἀμφότεροι</h1><div class=\"entry-meta\">adjetivo/pronome plural, -αι, -α · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμφότεροι, -αι, -α: ambos de dois, um e outro simultaneamente; Mateus 9.17 e outros. O neutro plural τὰ ἀμφότερα, «ambas as coisas», em Atos 23.8 e Efésios 2.14. Forma corrente desde Homero.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 9.17; At 23.8; Ef 2.14</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dudérepor, -ar, -a, [fr. Hom. down], both of two, both the \none and the other: Mt. ix. 17, etc.; 1a audédrepa, Acts \nxxiii. 8; Eph. ii. 14. \n38 av</p></section></article>\n<article id=\"entry-thayer-0312\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμώμητος\" data-meanings=\"sem censura; irrepreensível\">ἀμώμητος</h1><div class=\"entry-meta\">adjetivo, -ον · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀμώμητος, -ον, de μωμάομαι com alfa privativo: que não pode ser censurado, irrepreensível. Filipenses 2.15 segundo o texto recebido, com variantes críticas, e 2Pedro 3.14. Paralelos de Homero, Hesíodo, Píndaro e Plutarco.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Fp 2.15 (variante); 2Pe 3.14</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">G-papnTos, -ov, (uapdopar), that cannot be censured, \nblameless: Phil. ii. 15 RG (cf. réxva popnrd, Deut. \nxxx. 5); 2 Pet. iii. 14. (Hom. Il. 12, 109; [Hesioa, \nPind., al. ;] Plut. frat. amor. 18; often in Anthol.)*</p></section></article>\n<article id=\"entry-thayer-0313\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμον\" data-meanings=\"amomo; planta aromática\">ἄμωμον</h1><div class=\"entry-meta\">substantivo neutro, -ου · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἄμωμον, -ου, τό: amomo, nome antigo de planta aromática da Índia, de cujas sementes se extraía ingrediente para ungüentos; Apocalipse 18.13 nas edições críticas indicadas por Thayer. O autor remete à descrição de Plínio (*História Natural* 12.13). Trata-se de nome botânico histórico, sem identificação taxonômica moderna certificada.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Ap 18.13 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">Gpopov, -ov, 7d, amomum, a fragrant plant of India, \nhaving the foliage of the white vine [al. ampeloleuce] \nand seed, in clusters like grapes, from which ointment \nwas made (Plin. h. n. 12, 13 [28]): Rev. xviii. 13 GL \nTTrWH. [See B. D. Am. ed. s. v.]*</p></section></article>\n<article id=\"entry-thayer-0314\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμος\" data-meanings=\"sem defeito; imaculado; irrepreensível\">ἄμωμος</h1><div class=\"entry-meta\">adjetivo, -ον · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἄμωμος, -ον: sem mancha ou defeito, especialmente de vítima sacrificial (1Pedro 1.19; Hebreus 9.14), imagens aplicadas à vida sem pecado de Cristo. Por extensão ética, irrepreensível, livre de falta (Efésios 1.4; 5.27; Colossenses 1.22; Filipenses 2.15 em certas edições; Judas 24; Apocalipse 14.5). Thayer indica paralelos da Septuaginta e autores clássicos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">1Pe 1.19; Hb 9.14; Ef 1.4; 5.27; Cl 1.22; Jd 24; Ap 14.5</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">d-popos, -ov, (uamos), without blemish, free from faulti￾ness, as a victim without spot or blemish: 1 Pet. i. 19 \n(Lev. xxii. 21); Heb. ix. 14; in both places allusion is \nmade to the sinless life of Christ. Ethically, without \nblemish, faultless, unblamable: Eph. i. 4; v. 27; Col. i. \n22; Phil. ii 15 LT irWH; Jude 24; Rev. xiv...5, \n(Often in Sept.; [Hesiod, Simon., Iambl.], Hdt. 2, 177, \nAeschyl. Pers. 185; Theocr. 18, 25.) [Syn. see Trench \n§ ciii.; Tittmann i. 29 sq.]*</p></section></article>\n<article id=\"entry-thayer-0315\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀμών\" data-meanings=\"Amom; rei de Judá\">Ἀμών</h1><div class=\"entry-meta\">nome próprio masculino indeclinável · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">Ἀμών, nome próprio indeclinável: Amom, rei de Judá, filho de Manassés e pai de Josias (Mateus 1.10). Thayer assinala a variante Ἀμώς nas edições críticas; não confundir com o profeta homônimo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 1.10 (variante)</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">&quot;Apay, 6, indecl., Amon, (}\\8 artificer [but cf. B. D.]), \nking of Judah, son of Manasseh, and father of Josiah: \nMt.i.10, [LT Tr WH -pos. Cf. B. D.].*</p></section></article>\n<article id=\"entry-thayer-0316\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀμώς\" data-meanings=\"Amós; ancestral de Jesus\">Ἀμώς</h1><div class=\"entry-meta\">nome próprio masculino indeclinável · Thayer, p. 33, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">Ἀμώς, ὁ, forma indeclinável de nome próprio: Amós, um dos antepassados de Jesus (Lucas 3.25); também Mateus 1.10 em algumas edições críticas. Thayer distingue os textos e a variante do nome Ἀμών.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 1.10 (variante); Lc 3.25</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33, folhas PDF 57, coluna esquerda. O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">*Apds, 6, Amos, (y Was strong), indecl. prop. name of one \nof Christ’s ancestors: [Mt.i.10 L T Tr WH ]; Lk. iii. 25.*</p></section></article>\n<article id=\"entry-thayer-0317\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"33–34\" data-thayer-pdf-leaf=\"57\" data-thayer-column=\"direita (33); esquerda e direita (34)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄν\" data-meanings=\"partícula de possibilidade, condição e eventualidade\">ἄν</h1><div class=\"entry-meta\">partícula modal · Thayer, p. 33–34, direita (33); esquerda e direita (34)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἄν, partícula modal que assinala que algo poderia ocorrer sob determinadas condições ou causas fortuitas. Não possui correspondente constante no latim nem em advérbios modernos como «talvez». Thayer descreve extensamente seu funcionamento em orações hipotéticas e com formas temporais e modais.</p><p class=\"entry-text\">I. Na apódose de condicionais, com imperfeito do indicativo, indica resultado contrário à situação presente ou dependente de hipótese: Lucas 7.39; 17.6; Mateus 23.30; Gálatas 1.10. Com aoristo do indicativo, exprime o que teria ocorrido se dada condição se cumprisse (Mateus 11.21; 24.43; João 4.10; 14.2,28; Romanos 9.29; 1Coríntios 2.8), mesmo quando a condição não está explicitamente expressa. Aparece ainda com mais-que-perfeito (João 11.21) e em variações editoriais.</p><p class=\"entry-text\">II. Associado ao optativo, exprime possibilidade («poderia»). Na língua grega do NT, a partícula associa-se também a pronomes relativos e advérbios de lugar, tempo, qualidade ou maneira, adquirindo força de generalização ou eventualidade, próxima de «quem quer que», «onde quer que», «quando quer que»: ὃς ἄν, ὅπου ἄν, ὅταν (= ὅτε ἄν), ἐάν (= εἰ ἄν) etc. Thayer discute condições com subjuntivo, indicativo, possíveis omissões e variações textuais.</p><p class=\"entry-text\">O autor menciona casos em que ἄν aparece depois de conjunções, com comparações entre diversas edições e gramáticos (Winer, Buttmann, Goodwin, Klotz). A descrição sintática é apresentada de maneira panorâmica; para a distribuição exaustiva dos exemplos, prevalece o fac-símile.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Lc 7.39; 17.6; Mt 11.21; Jo 4.10; 14.2; Rm 9.29; 1Co 2.8; Mc 6.10; Mt 10.11; Ap 2.25</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 33–34, folhas PDF 57–58, coluna direita (33); esquerda e direita (34). O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">éy, a particle indicating that something can or could \noccur on certain conditions, or by the combination of \ncertain fortuitous causes. In Lat. it has no equivalent; \nnor do the Eng. haply, perchance, Germ. wohl (wol), \netwa, exactly and everywhere correspond to it. The \nuse of this particle in the N. T., illustrated by copious \nexx. fr. Grk. writ., is shown by W. § 42; [cf. B. 216 \n(186) sqq. Its use in classic Grk. is fully exhibited (by \nProf. Goodwin) in L. and S. s. v.]. \nIt is joined _I. in the apodoses of hypothetical sen￾tences 1. with the Impf., where the Lat. uses the \nimpf. subjunctive, e. g. Lk. vii. 39 (eyiveckey dy, sciret, \nhe would know) ; Lk. xvii. 6 (€Xéyere av ye would say) ; Mt. \nxxiii. 830 (non essemus, we should not have been); Jn. \nVero nevilledonwixe Alt xv 9s exvin.oo ly Co..xi. oi \nGal. i.10; iii. 21 [but WH mrg. br.]; Heb. iv. 8; viii. 4, \nie 2. with the indic. Aor. (where the Lat. uses the \nplpf. subj. like the fut. pf. subj., J would have done it), \nto express what would have been, if this or that either \nwere (ei with the impf. in the protasis preceding), or \nhad been (ei with the aor. or plpf. preceding): Mt. xi. \n21 and Lk. x. 13 (ay perevdnoay they would have re￾pented); Mt. xii 23; xii. 7 (ye would not have con￾demned); Mt. xxiv. 43 (he would have watched), 22 and \nMk. xiii. 20 (no one would have been saved, i.e. all even now \nwould have to be regarded as those who had perished ; \nef. W. 304 (286)); Jn. iv. 10 (thow wouldst have asked) ; \nxiv. 2 (e¢rov dv I would have said so); 28 (ye would have \nrejoiced); Ro. ix. 29 (we should have become); 1 Co. ii. \n8; Gal. iv. 15 (RG); Acts xviii. 14. Sometimes the \ncondition is not expressly stated, but is easily gathered \nfrom what is said: Lk. xix. 23 and Mt. xxv. 27 (J should \nhave received it back with interest, sc. if thou hadst given \nit to the bankers). 3. with the Plupf.: Jn. xi. 21 \n[R Tr mrg.] (ovk dy érebvnxer [LT Tr txt. WH ameOavev }\n[continua p. 34]\na av \nwould not have died, for which, in 32, the aor. od« ay \ndméOave); Jn. xiv. 7 [not Tdf.] (ef with the plpf. preced￾ing); 1 Jn. ii. 19 (they would have remained with us). \nSometimes (as in Grk. writ., esp. the later) dy is omitted, \nin order to intimate that the thing wanted but little \n(impf.) or had wanted but little (plpf. or aor.) of being \ndone, which yet was not done because the condition was \nnot fulfilled (cf. Alex. Bttm. in the Stud. u. Krit. for 1858, \np- 489 sqq.; [N. T. Gram. p. 225 (194)]; Fritzsche on \nRom. vol. ii. 33; W. § 42, 2 p. 305 (286)), e. g. In. vill. 39 \n(where the d is spurious); xv. 22, 24; xix. 11; Acts \nxxvi. 82; Ro. vii. 7; Gal. iv. 15 (@&amp; before edaxare \nhas been correctly expunged by LT TrWH). II. \nJoined to relative pronouns, relative adverbs, and ad￾verbs of time and quality, it has the same force as the \nLat. cumque or cunque, -ever, -soever, (Germ. irgend, \netwa). 1. foll. by a past tense of the Indicative, when \nsome matter of fact, something certain, is spoken of ; \nwhere, “when the thing itself which is said to have \nbeen done is certain, the notion of uncertainty involved \nin d&amp; belongs rather to the relative, whether pronoun or \nparticle” (Klotz ad Dev. p. 145) [ef. W. § 42, 3.a.]; daoe \ndy as many as: Mk. vi. 56 (dc00 dv rrovro [Ayavto L \ntxt. T Tr txt. WH] airod as many as touched him (cf. B. \n216 (187)]); Mk. xi. 24 (60a dy mpocevxdpevor aireiobe \n{Grsb. om. dy], but L txt. T Tr WH have rightly restored \nSoa mpocevyeabe x. aireiobe). KaOdre dv in so far or so often \nws, according as, (Germ. je nachdem gerade) : Acts ii. 45; \ntv. 85. as dv: 1 Co. xii. 2 (in whatever manner ye were \nled [ef. B. § 139, 13; 383(329)sq.]). 2. foll. bya Sub￾junctive, a. the Present, concerning that which \nmay have been done, or is usually or constantly done \n(where the Germ. uses mégen); nvixa dv whensoever, as \nofien as: 2 Co. iii. 15 L T Tr WH; os ay whoever, be he \nwho hemay: Mt. xvi. 25 (LT Tr WH eédy) ; [Mk. viii. 35 \n(where T Tr WH fut. indic.; see WH. App. p. 172)]; \nLk. x.5 (Lu T Tr WH aor.), 8; Gal. v.17 (T Tr WH éap, \nLbr. édv); 1 Jn. ii. 5; iii. 17; Ro. ix. 15 (Ex. xxxiii. 19); \nxvi. 2; 1 Co. xi. 27, ete. doris dv: 1 Co. xvi. 2 [Tr WH \neav; WH mrg. aor.]; Col. iii. 17 (Ltxt. Tr WH éav). dco \nav: Mt. vii. 12 (T WH eay); xxii. 9 (LT Tr WH dp). \nmov dv whithersoever: Lk. ix. 57 (L Tr édv); Rev. xiv. 4 \n(L Tr[T ed. 7 not 8, WH] have adopted imdye:, defended \nalso by B. 228 (196)); Jas. iii. 4 (RGLTrmrg. in \nbr.). dodkis av how often soever: 1 Co. xi. 25 sq. (where \nLT Tr WH eav). ds dy in what way soever: 1 Th. ii. 7 \n((ef. Ellic. ad loc.; B. 232 (200)], LT Tr WH éav). _b.. \nthe Aorist, where the Lat. uses the fut. pf.; ds dv: Mt. \nv. 21, 22 (etn whoever, if ever any one shall have said) ; \n31 sq. [in vs. 32 L T Tr WH read was 6 drodiar]; x. 11; xxvi. 48 (Tdf. edv); Mk. iii. 29, 35; ix.41,ete. darts av: Mt. x. 33 [L Tr WH txt. om. av]; xii. 50; Jn. xiv. 13 (Tr mrg. WH pres.]; Acts iii. 23 (Tdf. éav), ete. cou \nav: Mt. xxi. 22 (Treg. édv) ; xxiii. 3 (T WH éav); Mk. iii. \n28 (fr WH édy); Lk. ix. 5 (LT Tr WH pres.); Jn. xi. 22; Acts ii. 39 (Lehm. ods); iii. 22. Smov av: Mk. \nxiv. 9 (T WH eéav); ix. 18 (LT Tr WH edv). Gypis ov \ndy until (donec) : 1 Co. xv. 25 Rec.; Rev. ii. 25. fas dp \n34 \n| s€pos], (Polyb. 4, 20, 10 dvd pépos dew). \noh \nava \nuntil (usque dum): Mt. ii. 13; x. 11; xxii. 44; Mk. vi. \n10; Lk. xxi. 32; 1 Co. iv. 5, etc. nvixa ay, of fut. time, \nnot until then, when ...or then at length, when ...: 2Co. \niii. 16 (T WH txt. éav) [ef. Kiihner ii. 951; Jelf ii. 565). \nas ay as soon as [B. 232 (200)]: 1 Co. xi. 834; Phil. ii. \n23. ad’ ob dv éeyepOn, Lk. xiii. 25 (from the time, what￾ever the time is, when he shall have risen up). But éav \n(q. v-) is also joined to the pronouns and adverbs men￾tioned, instead of av; and in many places the Mss. and \nedd. fluctuate between dy and édy, (exx. of which have \nalready been adduced); [cf. Tdf. Proleg. p. 96; WH. \nApp. p. 173 “predominantly dy is found after conso￾nants, and éay after vowels”. Finally, to this head \nmust be referred érap (i. q. 6re dv) with the indic. and \nmuch oftener with the subj. (see érav), and dos dy, al￾though this last came to be used as a final conjunction \nin the sense, that, if it be possible: Lk. ii. 85; Acts iii. \n20 (19); xv.17; Ro. iii. 4; see das, II.1b. [Cf. W.309 \n(290 sq.); B. 234 (201).] III. dy is joined to the \nOptat. [W. 303 (284); B. 217 (188)]; when a certain \ncondition is laid down, as in wishes, J would that etc.: \nActs xxvi. 29 (evéaiunv [Tdf. evédyunv] dv I could pray, se. \ndid it depend on me) ; in direct questions [W.|1.c.; B. \n254 (219)]: Acts viii. 31 (és dv Suvaipny; i.e. on what \ncondition, by what possibility, could I? cf. Xen. oec. 11, \n5); Acts xvii. 18 (ri dy Odor. . . K€ yerv what would he \nsay ? it being assumed that he wishes to utter some defi￾nite notion or other); Acts ii. 12RG; in dependent \nsentences and indirect questions in which the nar￾rator introduces another’s thought [W. § 42,4; B.l.c.]: \nLk. i. 623 vi. 113 ix. 46; [xv.26 L br. Tr WH ef. xviii \n36 Lbr. Tr br. WH mrg.]; Acts v. 24; x. 17; xvii. 20 \nRG. IV. davis found without a mood in 1 Co. vii. 5 \n(ed pn te dv [WH br. dv], except perhaps, sc. yévouro, [but \ncf. Bttm. as below]). as dy, adverbially, tanquam (so \nalready the Vulg.), as if: 2 Co. x. 9 (like éomep dv in Grk. \nwrit. ; cf. Kiihner ii. 210 [§ 398 Anm. 4; Jelf § 430]; B. \n219 (189); [L. and S. s. v. D. III.)). \ndy, contr. from édy, 7f; foll. by the subjunc.: Jn. xx. \n23 [Lchm. éay. Also by the (pres.) indic. in 1 Jn. v. 15 \nLehm.; see B. 223 (192); W. 295 (277)]. Further, \nLT Tr WH have received dy in Jn. xiii. 20; xvi. 23; \n[so WH Jn. xii. 32; cf. W. 291 (274); B. 72 (63)].*</p></section></article>\n<article id=\"entry-thayer-0318\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"34–35\" data-thayer-pdf-leaf=\"58\" data-thayer-column=\"direita (34); esquerda (35)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνά\" data-meanings=\"acima; para cima; ao longo de; por; cada; de novo em composição\">ἀνά</h1><div class=\"entry-meta\">preposição com acusativo e elemento de compostos · Thayer, p. 34–35, direita (34); esquerda (35)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀνά: originalmente «para cima», «ao alto», oposta a κατά. Como preposição, pode indicar elevação ou distribuição; no NT ocorre com acusativo em locuções que indicam direção, distribuição ou repetição, por exemplo ἀνὰ μέσον («pelo meio de», «entre»), ἀνὰ δύο/τρεῖς («de dois em dois», «de três em três») e ἀνὰ μέρος («por turno»), conforme Thayer.</p><p class=\"entry-text\">Em composição com verbos e nomes pode (a) exprimir movimento para cima; (b) direção a determinado objetivo; (c) repetição, renovação ou recomeço («de novo»); (d) movimento de retorno; por vezes a distinção é atenuada e um composto aproxima-se semanticamente do simples. Thayer apresenta exemplos como ἀναβαίνω, ἀναγγέλλω, ἀναζάω e ἀναστρέφω. Referências a Winer, Buttmann e numerosos gramáticos clássicos, preservadas na extração OCR da própria fotografia.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 13.25; Mc 7.31; Ap 7.17; Jo 2.6; 1Co 14.27; Mt 20.17</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 34–35, folhas PDF 58–59, coluna direita (34); esquerda (35). O conteúdo a seguir é OCR bruto da fotografia e pode conter erros no grego e na pontuação. O testemunho impresso prevalece. Tradução resumida de trabalho, não certificada.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">ava, prep., prop. upwards, up, (cf. the adv. dve, opp. to \nxara and xdrw), denoting motion from a lower place to a \nhigher [cf. W. 398 (372) n.]; rare in the N. T. and only \nwith the accus. 1. in the expressions dva pécov (or \njointly avdpecor [so R* Tr in Rev. vii. 17]) into the midst, \nin the midst, amidst, among, between, — with gen. of place, \nMt. xiii. 25; Mk. vii. 31; Rev. vii. 17 [on this pass. see \npéoos, 2 sub fin.]; of pers., 1 Co. vi. 5, with which cf. \nSir. xxv. 18(17) dvd pécov rod (Fritz. rév) mdnolov adrod; \ncf. W.§ 27, 1 fin. [B. 332 (285) ], (Sir. xxvii. 2; 1 Mace. vii. \n28; xiii. 40, etc.; in Sept. for 713, Ex. xxvi. 28; Josh. \nXvi. 9; xix. 1; Diod. 2, 4 dvd pécov rav yerkwv [see pecos, \n2]); ava pepos, (Vulg. per partes), in turn, one after an￾other, in succession: 1 Co. xiv. 27 [where Rec* writes dva￾2. joined to\n[continua p. 35]\navaBabuos \nnumerals, it has a distributive force [W. 398 (372); B. 331 sq. (285)]: In. ii. 6 (dvd perpynras dv0 # rpeis two or three metrete apiece); Mt. xx. 9 sq. (¢daBov dva dyvdpioy they received each a denarius); Lk. ix. 3 [Tr br. WH om. avd; ix. 14]; x. 1 (dvd d00 [WH dvd dv0 [Sv0]] two by two); Mk. vi.40 (L T Tr WH xara); [Rev. iv. 8]; and \nvery often in Grk. writ.; cf. W. 398 (372). It is used \nadverbially in Rev. xxi. 21 (ava eis éxacros, like ava téa￾apes, Plut. Aem. 32; cf. W. 249 (234); [B. 30 (26) }). \n3. Prefixed to verbs dvd signifies, a. upwards, up, up \nto, (Lat. ad, Germ. auf), as in dvaxpovew, dvaBaivew, \ndvaBadrXeuv, avaxpatew, etc. b. it corresponds to the \nLat. ad (Germ. an), to [indicating the goal], as in dvay￾yéAdew (al. would refer this to d.], dvdmrew. ec. it de￾notes repetition, renewal, i. q. denuo, anew, over again, as \nd. it corresponds to the Lat. re, retro, back, \nCf. Win. \nin dvayevvav. \nbackwards, as in dvaxaurrewy, avaxywpeiv, etc. \nDe verb. comp. Pt. iii. p. 3 sq.*</p></section></article>\n";
